/// <summary>
/// Extension of the class <c>LedgerAllocationProcessRequest</c>
/// </summary>
[ExtensionOf(classStr(LedgerAllocationProcessRequest))]
final class AVALedgerAllocationProcessRequestCls_Extension
{
    private boolean copiedWithDifLayer_bec;
    private boolean postedWithDifLayer_bec;
    private boolean summarizeValues_bec;
    private boolean ruleArc_bec;
    private LedgerAllocationRuleDestination ruleDestination_bec;
    private DimensionDefault dimensionDefault_bec;
    private boolean rulePostedWithError;

}

Method.Source:
/// <summary>
/// Extension of the method <m>setDistributionValuesV2</m>
/// </summary>
/// <param name = "_ledgerDimensionId">ledger dimension id</param>
/// <param name = "_dimensionDefault">default dimension</param>
/// <param name = "_amountCur">amount cur.</param>
/// <param name = "_exchRate">exch. rate</param>
/// <param name = "_reportingExchRate">reporting exch.rate</param>
/// <param name = "_company">company</param>
protected void setDistributionValuesV2(RecId      _ledgerDimensionId,
                            DimensionDefault    _dimensionDefault,
                            AmountCur           _amountCur,
                            ExchRate            _exchRate,
                            ReportingCurrencyExchRate _reportingExchRate,
                            CompanyId           _company)

{
    DimensionAttributeValueSet  dimensionAttributeValueSet_bec;
    select firstonly MainAccountValue from dimensionAttributeValueSet_bec
        where dimensionAttributeValueSet_bec.RecId == dimensionDefault_bec;

    ledgerJournalTrans.Txt = strFmt("@NDX:NXAKoReAllocationJournalName",
        dimensionAttributeValueSet_bec.MainAccountValue,
        ledgerAllocationRule.AllocationDescription,
        glPostingDate);

    next setDistributionValuesV2(_ledgerDimensionId,
                                 _dimensionDefault,
                                 _amountCur,
                                 _exchRate,
                                 _reportingExchRate,
                                 _company);
}

/// <summary>
/// Extension of the method <m>getDimensionDefault</m>
/// </summary>
/// <param name = "_ruleDestination">rule destination</param>
/// <param name = "_ledgerAllocationTmpSource">table for allocation source</param>
/// <returns>default dimension</returns>
protected final DimensionDefault getDimensionDefault(LedgerAllocationRuleDestination _ruleDestination, LedgerAllocationTmpSource _ledgerAllocationTmpSource)
{
    ruleDestination_bec = _ruleDestination;
    dimensionDefault_bec = _ledgerAllocationTmpSource.DefaultDimension;
    return next getDimensionDefault(_ruleDestination, _ledgerAllocationTmpSource);
}

/// <summary>
/// Extension of the method createJournal
/// </summary>
/// <returns>created</returns>
protected boolean createJournal()
{
    ledgerJournalTable.AVACopiedWithDifLayer = copiedWithDifLayer_bec;
    boolean ret = next createJournal();

    if (ret && LedgerParameters::find().AVAKoRe)
    {
        ledgerJournalTable.selectForUpdate(true);
        ttsbegin;
        ledgerJournalTable.Name = strFmt("@NDX:NXAKoReAllocationJournalName", ledgerJournalTable.Name, ruleId, LedgerAllocationRule::find(ruleId).AVASequence);
        ledgerJournalTable.doUpdate();
        ttscommit;
    }

    return ret;
}

/// <summary>
/// parm method for copiedWithDifLayer_bec
/// </summary>
/// <param name = "_copiedWithDifLayer_bec">parm</param>
/// <returns>value</returns>
public boolean parmCopiedWithDifLayer_bec(boolean _copiedWithDifLayer_bec = copiedWithDifLayer_bec)
{
    copiedWithDifLayer_bec = _copiedWithDifLayer_bec;
    return copiedWithDifLayer_bec;
}

/// <summary>
/// parm method for postedWithDifLayer_bec
/// </summary>
/// <param name = "_postedWithDifLayer_bec">parm</param>
/// <returns>value</returns>
public boolean parmPostedWithDifLayer_bec(boolean _postedWithDifLayer_bec = postedWithDifLayer_bec)
{
    postedWithDifLayer_bec = _postedWithDifLayer_bec;
