}

/// <summary>
/// parm method for summarizeValues_bec
/// </summary>
/// <param name = "_summarizeValues_bec">summarize values parm</param>
/// <returns>value</returns>
public boolean parmSummarizeValues_bec(boolean _summarizeValues_bec = summarizeValues_bec)
{
    summarizeValues_bec = _summarizeValues_bec;
