}

/// <summary>
/// parm method for ledgerJournalName
/// </summary>
/// <param name = "_ledgerJournalName">parm</param>
/// <returns>value</returns>
public LedgerJournalName parmledgerJournalName_bec(LedgerJournalName _ledgerJournalName = ledgerJournalName)
{
    ledgerJournalName = _ledgerJournalName;
    return _ledgerJournalName;
}

/// <summary>
/// Extension of the method <m>allocate</m>
/// </summary>
public void allocate()
{
    next allocate();
    if (copiedWithDifLayer_bec)
    {
        LedgerJournalTable newLedgerJournalTable_bec = this.copyJournal_bec();

        if (summarizeValues_bec)
        {
            if (LedgerParameters::find().AVASummarizeAllocation)
            {
                this.summarizeValuesPerVoucher(newLedgerJournalTable_bec);
            }
            else
            {
                this.summarizeValues_bec(newLedgerJournalTable_bec);
            }
        }

        if (postedWithDifLayer_bec && newLedgerJournalTable_bec)
        {
            if (!rulePostedWithError)
            {
                LedgerJournalCheckPost ledgerJournalCheckPost_bec = LedgerJournalCheckPost::construct(newLedgerJournalTable_bec.JournalType);
                ledgerJournalCheckPost_bec.parmJournalNum(newLedgerJournalTable_bec.JournalNum);
                ledgerJournalCheckPost_bec.parmPost(true);
                LedgerJournalCheckPost::processOperation(ledgerJournalCheckPost_bec);
                if (ledgerJournalCheckPost_bec.parmPostingResults().errorInJournal())
                {
                    throw error (strFmt("@NDX:NXAAllocationJournalPostError", newLedgerJournalTable_bec.JournalNum));
                }
            }
        }
    }

    /*if (ruleArc_bec)
    {
        ledgerAllocationRule.arcRule_bec(asOfDate);
    }*/
}

private void summarizeValuesPerVoucher(LedgerJournalTable _ledgerJournalTable)
{

    LedgerJournalTrans ledgerJournalTrans;
    LedgerJournalTrans ledgerJournalTransForUpdate;
    LedgerJournalTrans ledgerJournalTransForDelete;
    ledgerJournalTrans ledgerJournalTransForGrouping, ljtDimension;
    MainAccount         mainAccount;
    container           conVouchers;
    Counter             i;
    //AmountCurCredit     sumCredit;
    //AmountCurDebit      sumDebit;
    QueryBuildDataSource    qbds;
    QueryRun                qr;
    //QueryBuildRange         qbr;
    Voucher                 voucher;
    Query                   query = new Query();

    delete_from ljtDimension where ljtDimension.JournalNum == _ledgerJournalTable.JournalNum &&
                                        ljtDimension.AmountCurCredit == 0 &&
                                        ljtDimension.AmountCurDebit == 0;

    //Gruppieren nach Konto
    while select accounttype,
                 LedgerDimension,
                 OffsetAccountType,
                 OffsetLedgerDimension
                 from ljtDimension
                 group by
                 ljtDimension.AccountType,
                 ljtDimension.LedgerDimension,
                 ljtDimension.OffsetAccountType,
                 ljtDimension.OffsetLedgerDimension
                 where ljtDimension.JournalNum == _ledgerJournalTable.JournalNum
    {
        //Wenn Konto zum Verdichten markiert
        mainaccount = MainAccount::findByLedgerDimension(ljtDimension.LedgerDimension);
        if (mainAccount.AVASumLedgerAllocation)
        {
            //suche alle Belegnummern mit Buchungen auf diesem Konto
            conVouchers = conNull();
            i = 1;
            while select accounttype,
                     LedgerDimension,
                     OffsetAccountType,
                     OffsetLedgerDimension,
                     Voucher
                     from ledgerJournalTransForGrouping
                     group by
                     ledgerJournalTransForGrouping.AccountType,
                     ledgerJournalTransForGrouping.LedgerDimension,
                     ledgerJournalTransForGrouping.OffsetAccountType,
                     ledgerJournalTransForGrouping.OffsetLedgerDimension,
                     ledgerJournalTransForGrouping.Voucher
                     where ledgerJournalTransForGrouping.JournalNum == _ledgerJournalTable.JournalNum
                        && ledgerJournalTransForGrouping.LedgerDimension == ljtDimension.LedgerDimension
            {
                conVouchers = conIns(conVouchers,i, ledgerJournalTransForGrouping.Voucher);
                i++;
            }
            //verdichte die gefundenen Belegnummern zu je einer Buchung pro Konto
            query = new Query();
            qbds = query.addDataSource(tableNum(ledgerJournalTrans));
            qbds.addGroupByField(fieldNum(LedgerJournalTrans, AccountType));
            qbds.addGroupByField(fieldNum(LedgerJournalTrans, LedgerDimension));
            qbds.addGroupByField(fieldNum(LedgerJournalTrans, OffsetAccountType));
            qbds.addGroupByField(fieldNum(LedgerJournalTrans, OffsetLedgerDimension));
            qbds.addSelectionField(fieldNum(LedgerJournalTrans, AmountCurCredit), SelectionField::Sum);
            qbds.addSelectionField(fieldNum(LedgerJournalTrans, AmountCurDebit), SelectionField::Sum);
            SysQuery::findOrCreateRange(qbds, fieldNum(LedgerJournalTrans, JournalNum)).value(_ledgerJournalTable.JournalNum);
            i = 1;
            while (i <= conLen(conVouchers))
            {
                qbds.addRange(fieldNum(LedgerJournalTrans, Voucher)).value(conPeek(conVouchers, i));
                i++;
            }
            qr = new QueryRun(query);
            while (qr.next())
            {
                ledgerJournalTrans = qr.get(tableNum(ledgerJournalTrans));
                voucher = conPeek(conVouchers, 1);
                ttsbegin;

                select firstonly forupdate * from ledgerJournalTransForUpdate
                where ledgerJournalTransForUpdate.JournalNum == _ledgerJournalTable.JournalNum
                && ledgerJournalTransForUpdate.Voucher == voucher
                && ledgerJournalTransForUpdate.AccountType == ledgerJournalTrans.AccountType
                && ledgerJournalTransForUpdate.LedgerDimension == ledgerJournalTrans.LedgerDimension
                && ledgerJournalTransForUpdate.OffsetAccountType == ledgerJournalTrans.OffsetAccountType
                && ledgerJournalTransForUpdate.OffsetLedgerDimension == ledgerJournalTrans.OffsetLedgerDimension;
                if (ledgerJournalTransForUpdate)
                {
                    ledgerJournalTransForUpdate.Voucher = voucher;
                    ledgerJournalTransForUpdate.AmountCurCredit = ledgerJournalTrans.AmountCurCredit;
                    ledgerJournalTransForUpdate.AmountCurDebit = ledgerJournalTrans.AmountCurDebit;
                    if (ledgerJournalTransForUpdate.AmountCurDebit && ledgerJournalTransForUpdate.AmountCurCredit)
                    {
                        if (ledgerJournalTransForUpdate.AmountCurDebit >= ledgerJournalTransForUpdate.AmountCurCredit)
                        {
                            ledgerJournalTransForUpdate.AmountCurDebit = ledgerJournalTransForUpdate.AmountCurDebit - ledgerJournalTransForUpdate.AmountCurCredit;
                            ledgerJournalTransForUpdate.AmountCurCredit = 0;
                        }
                        else if (ledgerJournalTransForUpdate.AmountCurCredit > ledgerJournalTransForUpdate.AmountCurDebit)
                        {
                            ledgerJournalTransForUpdate.AmountCurCredit = ledgerJournalTransForUpdate.AmountCurCredit - ledgerJournalTransForUpdate.AmountCurDebit;
                            ledgerJournalTransForUpdate.AmountCurDebit = 0;
                        }
                    }
                    ledgerJournalTransForUpdate.Txt = subStr(ledgerJournalTransForUpdate.Txt,strScan(ledgerJournalTransForUpdate.Txt,'-',1,strLen(ledgerJournalTransForUpdate.Txt)) + 2,strLen(ledgerJournalTransForUpdate.Txt));
                    ledgerJournalTransForUpdate.modifiedField(fieldNum(LedgerJournalTrans, AmountCurCredit));
                    ledgerJournalTransForUpdate.modifiedField(fieldNum(LedgerJournalTrans, AmountCurDebit));
                    ledgerJournalTransForUpdate.update();
                    while select forupdate ledgerJournalTransForDelete
                        where ledgerJournalTransForDelete.JournalNum == _ledgerJournalTable.JournalNum
                        && ledgerJournalTransforDelete.Voucher == voucher
                        && ledgerJournalTransForDelete.AccountType == ledgerJournalTrans.AccountType
                        && ledgerJournalTransForDelete.LedgerDimension == ledgerJournalTrans.LedgerDimension
                        && ledgerJournalTransForDelete.OffsetAccountType == ledgerJournalTrans.OffsetAccountType
                        && ledgerJournalTransForDelete.OffsetLedgerDimension == ledgerJournalTrans.OffsetLedgerDimension
                        && ledgerJournalTransForDelete.RecId != ledgerJournalTransForUpdate.RecId
                    {

                        ledgerJournalTransForDelete.doDelete();
                    }

                    i = 2;
                    while (i <= conLen(conVouchers))
                    {
                        voucher = conPeek(conVouchers, i);
                        while select forupdate ledgerJournalTransForDelete
                        where ledgerJournalTransForDelete.JournalNum == _ledgerJournalTable.JournalNum
                        && ledgerJournalTransforDelete.Voucher == voucher
                        && ledgerJournalTransForDelete.AccountType == ledgerJournalTrans.AccountType
                        && ledgerJournalTransForDelete.LedgerDimension == ledgerJournalTrans.LedgerDimension
                        && ledgerJournalTransForDelete.OffsetAccountType == ledgerJournalTrans.OffsetAccountType
                        && ledgerJournalTransForDelete.OffsetLedgerDimension == ledgerJournalTrans.OffsetLedgerDimension
                        && ledgerJournalTransForDelete.RecId != ledgerJournalTransForUpdate.RecId
                        {

                            ledgerJournalTransForDelete.doDelete();
                        }
                        i++;
                    }
                    /*while select forupdate ledgerJournalTransForDelete
                    where ledgerJournalTransForDelete.JournalNum == _ledgerJournalTable.JournalNum
                    && ledgerJournalTransForDelete.AccountType == ledgerJournalTrans.AccountType
                    && ledgerJournalTransForDelete.LedgerDimension == ledgerJournalTrans.LedgerDimension
                    && ledgerJournalTransForDelete.OffsetAccountType == ledgerJournalTrans.OffsetAccountType
                    && ledgerJournalTransForDelete.OffsetLedgerDimension == ledgerJournalTrans.OffsetLedgerDimension
                    && ledgerJournalTransForDelete.RecId != ledgerJournalTransForUpdate.RecId
                    {
                        if (conFind(conVouchers, ledgerJournalTransForDelete.Voucher))
                        {
                            ledgerJournalTransForDelete.doDelete();
                        }
                    }*/
                }
                ttscommit;
            }
        }
    }
}

/// <summary>
/// aggregate the journal lines
/// </summary>
/// <param name = "_ledgerJournalTable">journal table</param>
private void summarizeValues_bec(LedgerJournalTable _ledgerJournalTable)
{
    LedgerJournalTrans ledgerJournalTrans_bec;
    LedgerJournalTrans ledgerJournalTransForUpdate_bec;
    LedgerJournalTrans ledgerJournalTransForDelete_bec;
    MainAccount         mainAccount;

    while select
        AccountType,
        LedgerDimension,
        OffsetAccountType,
        OffsetLedgerDimension,
        //Voucher,
        sum(AmountCurCredit),
        sum(AmountCurDebit)
        from ledgerJournalTrans_bec
        group by
        ledgerJournalTrans_bec.AccountType,
        ledgerJournalTrans_bec.LedgerDimension,
        ledgerJournalTrans_bec.OffsetAccountType,
        //ledgerJournalTrans_bec.OffsetLedgerDimension,
        ledgerJournalTrans_bec.OffsetLedgerDimension
        //ledgerJournalTrans_bec.Voucher
        where ledgerJournalTrans_bec.JournalNum == _ledgerJournalTable.JournalNum
    {
        mainaccount = MainAccount::findByLedgerDimension(ledgerJournalTrans_bec.LedgerDimension);
        if (mainAccount.AVASumLedgerAllocation)
        {
            ttsbegin;
            select firstonly forupdate * from ledgerJournalTransForUpdate_bec
                where ledgerJournalTransForUpdate_bec.JournalNum == _ledgerJournalTable.JournalNum
                && ledgerJournalTransForUpdate_bec.AccountType == ledgerJournalTrans_bec.AccountType
                && ledgerJournalTransForUpdate_bec.LedgerDimension == ledgerJournalTrans_bec.LedgerDimension
                && ledgerJournalTransForUpdate_bec.OffsetAccountType == ledgerJournalTrans_bec.OffsetAccountType
                //&& ledgerJournalTransForUpdate_bec.OffsetLedgerDimension == ledgerJournalTrans_bec.OffsetLedgerDimension
                //&& ledgerJournalTransForUpdate_bec.Voucher == ledgerJournalTrans_bec.Voucher;
                && ledgerJournalTransForUpdate_bec.OffsetLedgerDimension == ledgerJournalTrans_bec.OffsetLedgerDimension;
            if (ledgerJournalTransForUpdate_bec)
            {
                ledgerJournalTransForUpdate_bec.AmountCurCredit = ledgerJournalTrans_bec.AmountCurCredit;
                ledgerJournalTransForUpdate_bec.AmountCurDebit = ledgerJournalTrans_bec.AmountCurDebit;
                ledgerJournalTransForUpdate_bec.modifiedField(fieldNum(LedgerJournalTrans, AmountCurCredit));
                ledgerJournalTransForUpdate_bec.modifiedField(fieldNum(LedgerJournalTrans, AmountCurDebit));
                ledgerJournalTransForUpdate_bec.update();

                delete_from ledgerJournalTransForDelete_bec
                    where ledgerJournalTransForDelete_bec.JournalNum == _ledgerJournalTable.JournalNum
                    && ledgerJournalTransForDelete_bec.AccountType == ledgerJournalTrans_bec.AccountType
                    && ledgerJournalTransForDelete_bec.LedgerDimension == ledgerJournalTrans_bec.LedgerDimension
                    && ledgerJournalTransForDelete_bec.OffsetAccountType == ledgerJournalTrans_bec.OffsetAccountType
                    && ledgerJournalTransForDelete_bec.OffsetLedgerDimension == ledgerJournalTrans_bec.OffsetLedgerDimension
                    //&& ledgerJournalTransForDelete_bec.Voucher == ledgerJournalTrans_bec.Voucher
                    && ledgerJournalTransForDelete_bec.RecId != ledgerJournalTransForUpdate_bec.RecId;
            }
            ttscommit;
        }
    }
}

/// <summary>
/// copy allocation journal to the daily journal
/// </summary>
/// <returns>ledger journal table, result</returns>
private LedgerJournalTable copyJournal_bec()
{
    LedgerJournalTable          newLedgerJournalTable_bec;
    LedgerJournalTrans          fromLedgerJournalTrans_bec;

    if (ledgerJournalTable && ledgerAllocationRule.AVACostAllocationJournal)
    {
        LedgerJournalName costAllocationJournalName_bec = LedgerJournalName::find(ledgerAllocationRule.AVACostAllocationJournal);
        ttsbegin;
        newLedgerJournalTable_bec.JournalType = costAllocationJournalName_bec.JournalType;
        newLedgerJournalTable_bec.JournalName = costAllocationJournalName_bec.JournalName;
        newLedgerJournalTable_bec.AVAAllocationRefRecId = ledgerJournalTable.RecId;
        newLedgerJournalTable_bec.initFromLedgerJournalName();
        newLedgerJournalTable_bec.insert();
        newLedgerJournalTable_bec.Name = strFmt("@NDX:NXAKoReAllocationJournalName", glPostingDate, ruleId, LedgerAllocationRule::find(ruleId).AllocationDescription);
        newLedgerJournalTable_bec.doUpdate();

        NumberSeq numSeq = NumberSeq::newGetVoucherFromId(costAllocationJournalName_bec.NumberSequenceTable);

        Voucher lastVoucher_bec;
        Voucher curVoucher_ber;
        LedgerJournalTrans          newLedgerJournalTrans_bec;
        RecordInsertList            rilLedgerJournalTrans_bec = new RecordInsertList(tableNum(LedgerJournalTrans));
        while select * from fromLedgerJournalTrans_bec
            where fromLedgerJournalTrans_bec.JournalNum == ledgerJournalTable.JournalNum
            && (fromledgerjournaltrans_bec.AmountCurCredit || fromLedgerJournalTrans_bec.AmountCurDebit)
        {
            newLedgerJournalTrans_bec.clear();
            newLedgerJournalTrans_bec.data(fromLedgerJournalTrans_bec);
            newLedgerJournalTrans_bec.JournalNum = newLedgerJournalTable_bec.JournalNum;
            if (lastVoucher_bec != fromLedgerJournalTrans_bec.Voucher)
            {
                curVoucher_ber = numSeq.voucher();
            }
            newLedgerJournalTrans_bec.Voucher = curVoucher_ber;
            //newLedgerJournalTrans_bec.insert();
            rilLedgerJournalTrans_bec.add(newLedgerJournalTrans_bec);
            lastVoucher_bec = fromLedgerJournalTrans_bec.Voucher;
        }
        rilLedgerJournalTrans_bec.insertDatabase();

        ttscommit;
    }
    return newLedgerJournalTable_bec;
}

// Determine the amounts to be allocated (from the ledger).
// This is done by reading the LedgerAllocationRuleSource rows for the supplied RuleID; building a
// query string from the values in those rows; and querying the Ledger using this derived string and
// the supplied start/end date range values.  The results are populated into the ledgerAllocationTmpSource table.
protected void getLedgerAmounts()
{
    next getLedgerAmounts();

    //LedgerAllocationRule    ledgerAllocationRule_bec = LedgerAllocationRule::find(ruleId);
    if (!LedgerParameters::find().AVAKoRe)
    {
        return;
    }

    //AVALedgerAllocationRuleOperationsTax ledgerAllocationRuleOperationsTax;
    AVAFPLLedgerAllocationRuleOperationsTax ledgerAllocationRuleOperationsTax;
    select * from ledgerAllocationRuleOperationsTax where ledgerAllocationRuleOperationsTax.RuleId == ruleId;
    if (ledgerAllocationRuleOperationsTax)
    {
        //delete created LedgerAllocationTmpSource
        LedgerAllocationTmpSource ledgerAllocationTmpSourceDel;
        delete_from ledgerAllocationTmpSourceDel
        where   ledgerAllocationTmpSourceDel.SessionId == sessionId()
        && ledgerAllocationTmpSourceDel.TimeStamp == processTimestamp;

        do
        {
            this.getLedgerAmounts_bec(ledgerAllocationRuleOperationsTax.CurrentOperationsTax);
            next ledgerAllocationRuleOperationsTax;
        }
        while (ledgerAllocationRuleOperationsTax);
    }
}

// Determine the amounts to be allocated (from the ledger, Operation layer).
private void getLedgerAmounts_bec(CurrentOperationsTax _currentOperationsTax)
{


    LedgerAllocationRuleSource ruleSource;
    Map dimensionRange = new Map(Types::Int64, Types::String);
    Set dimensionRangeIncludeEmpty = new Set(Types::Int64);
    str emptyQueryStr = SysQuery::valueEmptyString();
    DimensionAttributeRecId mainAccountDimAttrId = DimensionAttribute::getWellKnownDimensionAttribute(DimensionAttributeType::MainAccount);
    RecId keyValue;

    Query query = new Query();
    QueryBuildDataSource qbds = query.addDataSource(tableNum(GeneralJournalAccountEntry));

    // Add fields from GeneralJournalAccountEntry to query
    qbds.addSelectionField(fieldNum(GeneralJournalAccountEntry, TransactionCurrencyAmount), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(GeneralJournalAccountEntry, AccountingCurrencyAmount), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(GeneralJournalAccountEntry, ReportingCurrencyAmount), SelectionField::Sum);

    // Configure the query to do a Group By currency & account/dimension combination
    qbds.orderMode(OrderMode::GroupBy);
    qbds.addSortField(fieldNum(GeneralJournalAccountEntry, TransactionCurrencyCode));
    qbds.addSortField(fieldNum(GeneralJournalAccountEntry, LedgerDimension));

    QueryBuildDataSource qbdsHeader = qbds.addDataSource(tableNum(GeneralJournalEntry));
    qbdsHeader.joinMode(JoinMode::InnerJoin);
    qbdsHeader.fetchMode(QueryFetchMode::One2One);
    qbdsHeader.addLink(fieldNum(GeneralJournalAccountEntry, GeneralJournalEntry), fieldNum(GeneralJournalEntry, RecId));
    qbdsHeader.addRange(fieldNum(GeneralJournalEntry, PostingLayer)).value(queryValue(_currentOperationsTax));
    qbdsHeader.addRange(fieldNum(GeneralJournalEntry, Ledger)).value(SysQuery::value(Ledger::current()));

    QueryBuildRange qbr = qbdsHeader.addRange(fieldNum(GeneralJournalEntry, AccountingDate));
    qbr.value(SysQuery::range(startDate, endDate));

    // Build the account and dimension range string from LedgerAllocationRuleSource for this rule
    while select SourceCriteria, FieldSetting, SourceDimensionAttribute from ruleSource
        where ruleSource.RuleID == ruleId
    {
        if (ruleSource.SourceCriteria == '')
        {
            // empty SourceCriteria for dimensions needs to map to blank dimension
            ruleSource.SourceCriteria = emptyQueryStr;
        }

        // Get the key for the map
        keyValue = this.setRuleSourceFieldSetting(ruleSource, mainAccountDimAttrId);

        this.processRuleSourceCriteria(query, ruleSource);

        this.createRuleSourceCriteria(ruleSource, keyValue, emptyQueryStr, dimensionRange, dimensionRangeIncludeEmpty);
    }

    QueryBuildDataSource qbdsDavc = qbds.addDataSource(tableNum(DimensionAttributeValueCombination));
    qbdsDavc.joinMode(JoinMode::ExistsJoin);
    qbdsDavc.addLink(fieldNum(GeneralJournalAccountEntry, LedgerDimension), fieldNum(DimensionAttributeValueCombination, RecId));
    qbdsDavc.fetchMode(QueryFetchMode::One2One);

    LedgerAllocationProcessRequest::createDimensionRanges(qbdsDavc, dimensionRange.getEnumerator(), dimensionRangeIncludeEmpty);

    GeneralJournalAccountEntry result;
    LedgerAllocationTmpSource ledgerAllocationTmpSourceNew;
    LedgerAllocationTmpSource ledgerAllocationTmpSourceExisting;

    boolean haveAtLeastOne = false;
    QueryRun queryRun = new QueryRun(query);

    ttsbegin;

    while (queryRun.next())
    {
        result = queryRun.get(tableNum(GeneralJournalAccountEntry)) as GeneralJournalAccountEntry;

        if (haveAtLeastOne && result.TransactionCurrencyAmount == 0 && result.AccountingCurrencyAmount == 0 && result.ReportingCurrencyAmount == 0)
        {
            // skip results that sum to zero because they are not relevant after at
            // least one source record is created to ensure the journal is valid
            continue;
        }

        ledgerAllocationTmpSourceNew.clear();
        ledgerAllocationTmpSourceNew.SessionId = sessionId();
        ledgerAllocationTmpSourceNew.TimeStamp = processTimestamp;
        ledgerAllocationTmpSourceNew.CurrencyCode = result.TransactionCurrencyCode;

        // Break ledger dimension into default dimension information
        ledgerAllocationTmpSourceNew.DefaultDimension = LedgerDimensionDefaultingEngine::getDefaultDimension(
            LedgerDimensionDefaultingEngine::getDimensionSourcesForLedgerDimension(result.LedgerDimension));

        ledgerAllocationTmpSourceNew.LedgerDimension = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountRecId(
            LedgerDimensionFacade::getMainAccountRecIdFromLedgerDimension(result.LedgerDimension));

        if (LedgerAllocationTmpSource::find(
            ledgerAllocationTmpSourceExisting,
            ledgerAllocationTmpSourceNew.TimeStamp,
            ledgerAllocationTmpSourceNew.CurrencyCode,
            ledgerAllocationTmpSourceNew.LedgerDimension,
            ledgerAllocationTmpSourceNew.DefaultDimension,
            true))
        {
            ledgerAllocationTmpSourceExisting.AmountCur += result.TransactionCurrencyAmount;
            ledgerAllocationTmpSourceExisting.AmountMST += result.AccountingCurrencyAmount;
            ledgerAllocationTmpSourceExisting.AmountMSTSecond += result.ReportingCurrencyAmount;
            ledgerAllocationTmpSourceExisting.ExchRate = this.calcExchRate(ledgerAllocationTmpSourceExisting.AmountMST, ledgerAllocationTmpSourceExisting.AmountCur);
            ledgerAllocationTmpSourceExisting.ExchRateSecond = 0.0;
            ledgerAllocationTmpSourceExisting.update();
        }
        else
        {
            ledgerAllocationTmpSourceNew.AmountCur = result.TransactionCurrencyAmount;
            ledgerAllocationTmpSourceNew.AmountMST = result.AccountingCurrencyAmount;
            ledgerAllocationTmpSourceNew.AmountMSTSecond = result.ReportingCurrencyAmount;
            ledgerAllocationTmpSourceNew.ExchRate = this.calcExchRate(result.AccountingCurrencyAmount, result.TransactionCurrencyAmount);
            ledgerAllocationTmpSourceNew.ExchRateSecond = 0.0;
            ledgerAllocationTmpSourceNew.insert();

            haveAtLeastOne = true;
        }
    }

    ttscommit;
}
